import pytest

from bedrock_protocol import v1001, v2168, v2225

# generated by gophertunnel b8bd735:
# packet.CompletedUsingItem{UsedItemID: 780, UseMethod: packet.UseItemBrushingCompleted}
BRUSHING = bytes.fromhex("0c030f000000")

# generated by gophertunnel b8bd735:
# packet.CompletedUsingItem{UsedItemID: -1, UseMethod: -1}
NEGATIVE = bytes.fromhex("ffffffffffff")

GOLDENS = [
    pytest.param(v2225.CompletedUsingItemPacket(item_id=780, item_use_method=15), BRUSHING, id="brushing"),
    pytest.param(v2225.CompletedUsingItemPacket(item_id=-1, item_use_method=-1), NEGATIVE, id="negative"),
]


@pytest.mark.parametrize("version", [v1001, v2168, v2225])
def test_completed_using_item_is_packet_142(version):
    assert version.packets[142] is version.CompletedUsingItemPacket


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_completed_using_item_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_completed_using_item_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet


def test_completed_using_item_rejects_a_body_short_of_its_second_field():
    with pytest.raises(ValueError, match="at byte"):
        v2225.CompletedUsingItemPacket.from_bytes(BRUSHING[:5])
